import React from 'react';

const OtherSkills = () => {
    return (
        <div className="otherSkills">
            <h3>Autres compétences</h3>
            <div className="list">
                <ul>
                    <li><i className="fas fa-check-square"></i>
                    Anglais courant</li>
                    <li><i className="fas fa-check-square"></i>
                    Github</li>
                    <li><i className="fas fa-check-square"></i>
                    SEO</li>
                </ul>

            </div>
            OtherSkills
        </div>
    );
};

export default OtherSkills;
